/// Create a new schematic evaluator job. An optional Idempotency-Key HTTP header (1 to 256 bytes) returns the same job for the same caller and RunSpec. Reusing a key with another RunSpec is refused.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `job` - The description of the job to create
///
/// Returns
/// * The ID of the newly created job
pub async fn create_job(ctx: &dyn RequestContext, job: RunSpec) -> Result<ObjectId, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/jobs";
    let body = Bytes::from(job.to_fbs_bytes());
    let res = ctx
        .post(&path, body, "application/octet-stream", None, None)
        .await?;
    crate::types::ObjectId::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Fetch the details of the job with the given ID. By default this will block until the job is complete.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the job to fetch
/// * `timeout` - Timeout in milliseconds to wait before returning a response
///
/// Returns
/// * The details of the job
pub async fn get_job(
    ctx: &dyn RequestContext,
    id: crate::types::id::ObjectId,
    timeout: Option<i64>,
) -> Result<Job, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/jobs/:id".replace(":id", &id.to_string());
    let mut params = ParamMap::new();
    if let Some(val) = timeout {
        params.insert("timeout".to_owned(), val.to_string());
    }

    let res = ctx.get(&path, Some(params), None).await?;
    crate::types::Job::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Cancel the job with the given ID: every task of it that has not ended is ended with `cancelled`. The intent is recorded at once and carried out by the evaluator; a task that completed before the intent arrived stays complete.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the job to cancel
pub async fn cancel_job(
    ctx: &dyn RequestContext,
    id: crate::types::id::ObjectId,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/schematicevaluator/jobs/:id".replace(":id", &id.to_string());
    ctx.delete(&path, None, None).await?;
    Ok(())
}

/// The evaluator's own state: whether the answering pod runs the kernel, its pools by task kind, the work still outstanding by kind, and the launcher it starts bundle runs with.
///
/// # Arguments
///
/// * `ctx` - A request context object
///
/// Returns
/// * The evaluator's state
pub async fn get_health(ctx: &dyn RequestContext) -> Result<EvaluatorHealth, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/health";
    let res = ctx.get(&path, None, None).await?;
    serde_json::from_slice(&res).map_err(Error::from)
}

/// Fetch the details of the task with the given ID.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The ID of the task to fetch
///
/// Returns
/// * The details of the task
pub async fn get_task(
    ctx: &dyn RequestContext,
    id: crate::types::id::ObjectId,
) -> Result<Task, Error> {
    let path = "/v1/api/ulv2/schematicevaluator/tasks/:id".replace(":id", &id.to_string());
    let res = ctx.get(&path, None, None).await?;
    crate::types::Task::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Insert an inline graph immediately after this task. Exact repeats return 409.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `id` - The task after which to insert the graph
/// * `continuation` - The inline schematic and its parameters
///
/// Returns
/// * The created task IDs in schematic node order
pub async fn set_graph_continuation(
    ctx: &dyn RequestContext,
    id: crate::types::id::ObjectId,
    continuation: ContinuationSpec,
) -> Result<ObjectIdList, Error> {
    let path =
        "/v1/api/ulv2/schematicevaluator/tasks/:id/continuations".replace(":id", &id.to_string());
    let body = Bytes::from(continuation.to_fbs_bytes());
    let res = ctx
        .post(&path, body, "application/octet-stream", None, None)
        .await?;
    crate::types::ObjectIdList::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

